import numpy as np

def select_next_node(current_node, depot, unvisited_nodes, rest_capacity, demands, distance_matrix):
    """Return an int from unvisited_nodes (or 0 to return to depot early when current_node != 0)."""
    uv = np.asarray(unvisited_nodes, dtype=np.int64)
    if uv.size == 0:
        return int(depot)

    scale = float(np.mean(distance_matrix[depot, 1:]))
    if not np.isfinite(scale) or scale <= 0.0:
        scale = 1.0

    d_cur = distance_matrix[current_node, uv].astype(np.float64)
    d_dep = distance_matrix[depot, uv].astype(np.float64)
    dem = np.asarray(demands, dtype=np.float64)[uv]

    # dimensionless depot savings: visiting next then depot vs. returning now
    savings = (d_dep - d_cur) / scale

    # capacity-fill regime: when capacity is tight, prefer small demands
    fill_ratio = float(rest_capacity) / max(float(np.max(np.asarray(demands, dtype=np.float64))), 1e-12)
    if fill_ratio < 1.5:
        demand_pen = (dem / max(float(rest_capacity), 1e-12))
    else:
        demand_pen = 0.0 * dem

    # slight nearest-neighbor tie-breaking term
    nn = d_cur / scale

    scores = savings - 0.35 * demand_pen - 0.05 * nn

    # voluntary early return when remaining capacity is small or nearest feasible customer is far
    if current_node != depot:
        nearest_norm = float(np.min(nn)) if nn.size > 0 else np.inf
        cap_small = (float(rest_capacity) / max(scale, 1e-12)) < 0.75
        far_next = nearest_norm > 0.9
        if cap_small and far_next:
            return int(depot)

    best = int(np.argmax(scores))
    return int(uv[best])
